{
  "avaliacoes": [
    {
      "id": "E42e8db3a2cf478c9",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "Em inspeção por boroscópio no interior do I-Tube de um riser de produção de FPSO, foi observado contato do riser com a parede do I-Tube próximo à entrada do bend stiffener, com confirmação de vazamento por bolhas durante injeção de N2 no anular.",
          "trechos": [
            "E42e8db3a2cf478c9:0:694",
            "E42e8db3a2cf478c9:694:1392"
          ],
          "condicoes": [
            "inspeção realizada a partir de janelas existentes abaixo do hang-off",
            "injeção de nitrogênio no anular repetida durante a boroscopia"
          ],
          "limites": [
            "caso específico de um FPSO e de um riser de produção",
            "não foram visualizados danos diretamente no ponto de contato",
            "não houve visualização de bolhas abaixo do nível de contato"
          ]
        },
        {
          "proposicao": "A inspeção indicou que o riser não estava centralizado dentro do I-Tube, o que é relevante para controle geométrico e transferência de cargas na região de hang-off e bend stiffener.",
          "trechos": [
            "E42e8db3a2cf478c9:0:694",
            "E42e8db3a2cf478c9:694:1392"
          ],
          "condicoes": [
            "conclusão baseada em inspeção visual por boroscópio"
          ],
          "limites": [
            "não quantifica excentricidade",
            "não estabelece critério geral de aceitação"
          ]
        },
        {
          "proposicao": "Após a detecção do contato, foi recomendado estudo numérico para reproduzir a forma deformada do riser no I-Tube considerando condições de hang-off e bend stiffener, com objetivo de avaliar se o contato era esperado, permanente ou intermitente, e se haveria outros pontos de contato não acessíveis ao boroscópio.",
          "trechos": [
            "E42e8db3a2cf478c9:694:1392",
            "E42e8db3a2cf478c9:1392:2085"
          ],
          "condicoes": [
            "situação em que a inspeção visual tem alcance limitado",
            "necessidade de considerar condições de hang-off e bend stiffener"
          ],
          "limites": [
            "trata-se de recomendação ligada ao caso analisado",
            "o próprio texto registra áreas não alcançáveis por boroscópio, como a folga do bend stiffener"
          ]
        }
      ]
    },
    {
      "id": "E2bdb321be05fc75a",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "O teste com nitrogênio é apresentado como adequado para determinar a condição do anular, mas com incertezas que levam à recomendação de monitoramento frequente para maior confiabilidade dos resultados.",
          "trechos": [
            "E2bdb321be05fc75a:0:700"
          ],
          "condicoes": [
            "aplicado à avaliação da condição do anular"
          ],
          "limites": [
            "o texto reconhece explicitamente incertezas do método",
            "não fornece critérios quantitativos de aceitação"
          ]
        },
        {
          "proposicao": "Na campanha relatada, o teste anular apontou possível vazamento em riser de produção e localizou a faixa provável dentro do I-Tube, próxima ao bend stiffener, em alguns metros acima ou abaixo dessa região.",
          "trechos": [
            "E2bdb321be05fc75a:0:700"
          ],
          "condicoes": [
            "resultado de campanha de teste anular específica"
          ],
          "limites": [
            "localização apenas aproximada",
            "resultado restrito ao caso relatado"
          ]
        },
        {
          "proposicao": "Após o teste anular, a decisão operacional foi executar boroscopia no interior do I-Tube, e a repetição da injeção de nitrogênio durante a inspeção confirmou o vazamento por bolhas na região de contato entre riser e I-Tube.",
          "trechos": [
            "E2bdb321be05fc75a:1394:2093"
          ],
          "condicoes": [
            "uso das janelas de inspeção existentes abaixo do hang-off",
            "combinação de teste com N2 e inspeção visual"
          ],
          "limites": [
            "não substitui análise estrutural das causas do contato",
            "confirmação vinculada à visualização de bolhas no caso observado"
          ]
        }
      ]
    },
    {
      "id": "Ea24d90b25a387401",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O bend stiffener é descrito como controlador de curvatura usado em aplicações com carregamentos dinâmicos e também, em aplicações estáticas, para proteção do duto durante a instalação.",
          "trechos": [
            "Ea24d90b25a387401:0:693",
            "Ea24d90b25a387401:693:1392"
          ],
          "condicoes": [
            "segundo referência citada no próprio texto para controladores de curvatura",
            "aplicável à interface entre duto/riser flexível e estrutura"
          ],
          "limites": [
            "o trecho não define limites operacionais nem critérios de dimensionamento",
            "menciona usos típicos, não uma regra universal"
          ]
        },
        {
          "proposicao": "A função técnica atribuída ao bend stiffener é promover transição suave de rigidez entre o riser flexível, mais complacente, e a estrutura da plataforma, mais rígida, influenciando a transferência de cargas na conexão.",
          "trechos": [
            "Ea24d90b25a387401:0:693",
            "Ea24d90b25a387401:693:1392"
          ],
          "condicoes": [
            "na interface com a plataforma"
          ],
          "limites": [
            "não apresenta verificação estrutural nem validação experimental no trecho"
          ]
        },
        {
          "proposicao": "No arranjo de bend stiffener para boca de sino com I-Tube, o ponto de aplicação das cargas verticais no conector fica desacoplado do ponto de aplicação da flexão na região do bend stiffener, e o texto afirma que essa característica é mais favorável para o riser flexível.",
          "trechos": [
            "Ea24d90b25a387401:1392:2091"
          ],
          "condicoes": [
            "aplicável a sistemas de conexão tipo bellmouth com I-Tube",
            "conector apoiado ao nível do convés e bend stiffener instalado em estrutura presa à boca de sino"
          ],
          "limites": [
            "o trecho descreve a característica e uma avaliação favorável, mas não quantifica ganhos nem critérios de seleção"
          ]
        }
      ]
    },
    {
      "id": "E0eba900d8ea97f55",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Em testes de vida útil e fadiga de risers, a majoração de carregamentos é apresentada como solução prática para obter falha em tempo viável, mas com a ressalva de que essa majoração não deve violar outros limitantes do tubo para evitar falhas não relacionadas à fadiga.",
          "trechos": [
            "E0eba900d8ea97f55:0:688"
          ],
          "condicoes": [
            "contexto de ensaios acelerados",
            "quando reproduzir fielmente cargas de serviço é impraticável"
          ],
          "limites": [
            "não trata diretamente de operação de pull-in em campo",
            "não informa limites quantitativos"
          ]
        },
        {
          "proposicao": "Quando a bancada de ensaio não consegue variar dinamicamente a tração, o texto indica que devem ser gerados carregamentos de flexão equivalentes para representar também o dano associado à variação de tração não simulada.",
          "trechos": [
            "E0eba900d8ea97f55:1381:2077"
          ],
          "condicoes": [
            "aplicável a bancadas que variam apenas flexão"
          ],
          "limites": [
            "é uma orientação para ensaio, não para operação offshore",
            "não detalha método de equivalência"
          ]
        },
        {
          "proposicao": "Bancadas que separam o ponto de aplicação da flexão do ponto de ancoragem axial do riser são apresentadas como simulação do uso de I-Tubes de FPSOs, enquanto bancadas sem essa característica são ditas mais indicadas para risers com bend stiffener tradicional montado no conector.",
          "trechos": [
            "E0eba900d8ea97f55:1381:2077",
            "E0eba900d8ea97f55:2077:2196"
          ],
          "condicoes": [
            "comparação entre arranjos de bancada para ensaio"
          ],
          "limites": [
            "relação baseada em representatividade de ensaio",
            "não substitui comprovação de campo"
          ]
        }
      ]
    },
    {
      "id": "Ebd32d69dc0588219",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O bend stiffener é definido como equipamento que suaviza a curvatura do riser flexível próximo à terminação na plataforma por meio de enrijecimento progressivo até a terminação.",
          "trechos": [
            "Ebd32d69dc0588219:0:699",
            "Ebd32d69dc0588219:699:1396"
          ],
          "condicoes": [
            "aplicado à terminação do riser na plataforma"
          ],
          "limites": [
            "definição conceitual sem critérios de projeto, inspeção ou aceitação"
          ]
        },
        {
          "proposicao": "O riser é definido como duto que liga o fundo do oceano à superfície em instalações marítimas, podendo ser rígido ou flexível, o que delimita o escopo dos elementos de conexão e controle geométrico tratados.",
          "trechos": [
            "Ebd32d69dc0588219:1396:2096"
          ],
          "condicoes": [
            "contexto de instalações marítimas de perfuração, completação ou produção"
          ],
          "limites": [
            "glossário; não aborda mecanismo de transferência de cargas"
          ]
        },
        {
          "proposicao": "O stress-joint é descrito como componente com função semelhante à do bend stiffener, aumentando progressivamente a rigidez, porém normalmente em titânio e para uso em dutos rígidos, o que ajuda a diferenciar compatibilidades entre soluções de conexão.",
          "trechos": [
            "Ebd32d69dc0588219:1396:2096"
          ],
          "condicoes": [
            "comparação funcional entre soluções para dutos/risers"
          ],
          "limites": [
            "não traz critérios de seleção nem limites de aplicação"
          ]
        }
      ]
    },
    {
      "id": "E3e87d7c7ff675b6a",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Na verificação do riser, o texto orienta inspecionar indícios de deformação, torção, vazamentos inclusive sob acessórios e bend stiffener, além da estanqueidade da capa externa por injeção de nitrogênio quando necessário.",
          "trechos": [
            "E3e87d7c7ff675b6a:0:692"
          ],
          "condicoes": [
            "atividade de inspeção e verificação",
            "teste de injeção de nitrogênio apenas quando necessário"
          ],
          "limites": [
            "lista de verificação sem critérios quantitativos de aceitação",
            "não especifica periodicidade"
          ]
        },
        {
          "proposicao": "Para o conector, o texto recomenda verificar integridade, corrosão, fixações, válvulas de alívio de gás permeado, fixação do riser ao hang-off e integridade da interface entre spool rígido e conector de topo, incluindo o sistema de monitoramento do espaço anular.",
          "trechos": [
            "E3e87d7c7ff675b6a:692:1385",
            "E3e87d7c7ff675b6a:1385:2072"
          ],
          "condicoes": [
            "verificação com registro fotográfico"
          ],
          "limites": [
            "não apresenta limites de desgaste, corrosão ou folga"
          ]
        },
        {
          "proposicao": "Para o enrijecedor de curvatura, o texto recomenda identificar se é bipartido ou inteiriço e verificar sua integridade, o sistema de fixação ao conector e, no caso dos bipartidos, as abraçadeiras de fixação.",
          "trechos": [
            "E3e87d7c7ff675b6a:1385:2072"
          ],
          "condicoes": [
            "inspeção com registro fotográfico",
            "distinção conforme o tipo de enrijecedor"
          ],
          "limites": [
            "não informa método de aceitação das não conformidades"
          ]
        }
      ]
    }
